package main

import (
	"fmt"
)

func main() {
	var a, b, c, d int
	fmt.Scan(&a, &b, &c, &d)

	v256 := 256
	v32 := 32

	x := min(a, min(c, d))
	ans := x*v256 + min(b, a-x)*v32

	fmt.Println(ans)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

